/**
 * What a new pdt project gets from what the module project says about itself: the module's id, from
 * `module.json`, is the project's id, which names its VTT, and the Foundry VTT version the project
 * was created for, from `.foundryvtt/.env`, is the version the VTT runs.
 *
 * Both files are read the same way whether the module was generated by `pdt init` or existed
 * already.
 */
import fs from 'node:fs';
import path from 'node:path';
import { DEFAULT_DOCKER_IMAGE, type VttSettings } from '@schema/config.js';
import { m } from '@i18n/messages.js';

/** The module's manifest, relative to the project. */
export const MODULE_MANIFEST = 'module.json';

/** The environment file of the project's Foundry VTT setup, relative to the project. */
export const FOUNDRY_ENV = path.join('.foundryvtt', '.env');

/** The variable in {@link FOUNDRY_ENV} that holds the Foundry VTT version. */
export const VERSION_VARIABLE = 'VERSION';

/** What was found out, or why it could not be. */
export type Found<T> = { value: T } | { problem: string };

function reasonOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** The module's id, from its manifest in `dir`. */
export function readModuleId(dir: string): Found<string> {
  const file = path.join(dir, MODULE_MANIFEST);
  const problem = (reason: string) => ({ problem: m['warn.projectVtt.noModuleId']({ file, reason }) });
  let manifest: unknown;
  try {
    manifest = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    return problem(reasonOf(error));
  }
  const id = typeof manifest === 'object' && manifest !== null ? (manifest as { id?: unknown }).id : undefined;
  if (typeof id !== 'string' || id === '') return problem(m['warn.projectVtt.reason.noId']());
  // The id becomes a configuration key, whose parts are separated by dots.
  if (id.includes('.')) return problem(m['warn.projectVtt.reason.idWithDot']({ id }));
  return { value: id };
}

/**
 * The variables in an environment file: a `NAME=value` on each line, with blank lines, comments and
 * an `export ` prefix allowed, and a value optionally in quotes.
 */
export function parseEnv(text: string): Record<string, string> {
  const variables: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim().replace(/^export\s+/, '');
    const at = line.indexOf('=');
    if (line === '' || line.startsWith('#') || at <= 0) continue;
    const value = line.slice(at + 1).trim();
    variables[line.slice(0, at).trim()] = /^(["']).*\1$/.test(value) ? value.slice(1, -1) : value;
  }
  return variables;
}

/** The Foundry VTT version the project was created for, from its environment file in `dir`. */
export function readFoundryVersion(dir: string): Found<string> {
  const file = path.join(dir, FOUNDRY_ENV);
  const problem = (reason: string) => ({ problem: m['warn.projectVtt.noFoundryVersion']({ file, reason }) });
  let text: string;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (error) {
    return problem(reasonOf(error));
  }
  const version = parseEnv(text)[VERSION_VARIABLE];
  if (version === undefined || version === '') {
    return problem(m['warn.projectVtt.reason.noVersion']({ variable: VERSION_VARIABLE }));
  }
  return { value: version };
}

/** The settings of a project's VTT: Foundry VTT `version`, in Docker. */
export function vttSettings(version: string): VttSettings {
  return {
    server: { type: 'foundry', hostname: 'localhost', version, port: 'auto' },
    host: { type: 'docker', image: DEFAULT_DOCKER_IMAGE, ports: [{ internal: 30000, external: 'auto' }] },
  };
}

/** The settings of the project's VTT, or why they cannot be worked out, with the command that would add them later. */
export type ProjectVtt = { settings: VttSettings } | { problem: string; command: string };

/**
 * The VTT for the module project in `dir`, named by the project's id.
 *
 * @param dir - The project's root directory
 * @param id - The project's id, which names its VTT
 */
export function projectVtt(dir: string, id: string): ProjectVtt {
  const version = readFoundryVersion(dir);
  if ('value' in version) return { settings: vttSettings(version.value) };
  return {
    problem: version.problem,
    command: `pdt config set VTT.${id} '${JSON.stringify(vttSettings('<version>'))}'`,
  };
}
